def _bao(
    handler: Callable[[httpx.Request], httpx.Response],
    *,
    addr: str = "http://openbao:8200",
    mount: str = "secret",
) -> OpenBaoSecretStore:
    return OpenBaoSecretStore(
        addr,
        "s3cr3t-token",
        mount=mount,
        client=httpx.Client(base_url=addr, transport=httpx.MockTransport(handler)),
    )


